async function main() {
  console.log("Writing authentic SVGs to public/logos/...");
  for (const [slug, svg] of Object.entries(AUTHENTIC_SVGS)) {
    const filePath = path.join(process.cwd(), "public/logos", `${slug}.svg`);
    fs.writeFileSync(filePath, svg.trim() + "\n", "utf-8");
    console.log(`✓ Wrote public/logos/${slug}.svg (${fs.statSync(filePath).size} bytes)`);
  }

  // Handle overlay: remove synthetic SVG, keep authentic 1024x1024 PNG
  const overlaySvgPath = path.join(process.cwd(), "public/logos/overlay.svg");
  if (fs.existsSync(overlaySvgPath)) {
    fs.unlinkSync(overlaySvgPath);
    console.log("✓ Removed synthetic public/logos/overlay.svg (using authentic overlay.png)");
  }

  const all19Slugs = [
    "liquid-d1",
    "overlay",
    "openclaw",
    "t3-code",
    "cube-computer",
    "openai-dot",
    "atomic-bot",
    "mirage-app",
    "deepseek-harness",
    "comma-ai",
    "laya-engine",
    "clef-flash",
    "glide-decision-model",
    "mai-transcribe-2-streaming",
    "mai-voice-2-1",
    "mai-voice-2-flash",
    "seedream-5-flash",
    "lm-studio",
    "vesence",
  ];

  console.log("\nUpdating SQLite database...");
  for (const slug of all19Slugs) {
    const logoUrl = slug === "overlay" ? "/logos/overlay.png" : `/logos/${slug}.svg`;
    await db.tool.updateMany({
      where: { slug },
      data: { logoUrl },
    });
    console.log(`✓ SQLite: ${slug} -> ${logoUrl}`);
  }

  console.log("\nUpdating Convex database...");
  const convex = createServerConvexClient();
  if (!convex) throw new Error("No Convex client available");

  for (const slug of all19Slugs) {
    const logoUrl = slug === "overlay" ? "/logos/overlay.png" : `/logos/${slug}.svg`;
    try {
      const page = await convex.query(api.tools.pageData, { slug });
      if (!page?.tool?.id) {
        console.warn(`Tool ${slug} not found in Convex!`);
        continue;
      }
      await convex.mutation(api.adminCrud.toolPatch, {
        toolLegacyId: page.tool.id,
        data: {},
        logoUrl,
        nowMs: Date.now(),
      });
      console.log(`✓ Convex: Patched ${slug} -> ${logoUrl}`);
    } catch (err) {
      console.error(`✗ Error patching ${slug} in Convex:`, err);
    }
  }

  console.log("\nVerifying logo paths on disk:");
  for (const slug of all19Slugs) {
    const ext = slug === "overlay" ? "png" : "svg";
    const p = path.join(process.cwd(), "public/logos", `${slug}.${ext}`);
    const exists = fs.existsSync(p);
    const size = exists ? fs.statSync(p).size : 0;
    console.log(`  ${slug}.${ext}: exists=${exists}, size=${size} bytes`);
  }

  console.log("\nAll 19 tools updated with authentic brand logos!");
}

main()
  .catch((e) => {
    console.error("Error in patch script:", e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });
